@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; animation-delay: 0s !important; transition-duration: 0.01ms !important; }
  .stage-glow { animation: none; }
  [data-animate], .slide.active [data-animate] { opacity: 1; animation: none; }
  .slide.active .prog-step, .slide.active .term-body .ln { opacity: 1; animation: none; }
}

/* ============================================================
   Marvin's cameos — a corner appearance on a handful of slides.
   Mood comes from the slide's data-marvin; the face is the same
   visor as assets/marvin-face.png, redrawn so the eyes can act.
   ============================================================ */
.marvin-hud {
  position: fixed; z-index: 45; right: 1.8rem; bottom: 3.6rem;
  display: flex; align-items: center; justify-content: flex-end; gap: 0.75rem;
  pointer-events: none;
  opacity: 0; visibility: hidden; transform: translateY(14px) scale(0.85);
  transition: opacity 0.45s var(--ease-out), transform 0.45s var(--ease-out),
              visibility 0s linear 0.45s;
}
.marvin-hud.is-on {
  opacity: 1; visibility: visible; transform: none; transition-delay: 0s;
}

.marvin-cameo {
  position: relative; display: block; width: 64px; flex: none;
  animation: marvin-float 4.5s ease-in-out infinite;
}
.marvin-svg {
  width: 100%; display: block;
  filter: drop-shadow(0 6px 18px rgba(81, 162, 255, 0.32));
  transition: transform 0.4s var(--ease-out);
}
.mv-face { fill: url(#mv-body); stroke: #55a6ba; stroke-width: 2.5; }
.mv-chin { fill: #16323f; }
.mv-eye {
  fill: #f4fbfc;
  transform-box: fill-box; transform-origin: center;
  transition: transform 0.4s var(--ease-out), fill 0.4s var(--ease-out);
}
.mv-shades {
  fill: #04151b; stroke: #55a6ba; stroke-width: 2;
  transform-box: fill-box; transform-origin: center top;
  transform: scaleY(0); opacity: 0;
  transition: transform 0.35s var(--ease-out), opacity 0.2s var(--ease-out);
}
.mv-emote {
  position: absolute; top: -0.75rem; right: -0.6rem;
  font-family: var(--font-mono); font-size: 0.82rem; font-weight: 700;
  color: var(--accent); line-height: 1;
}

.marvin-say {
  max-width: 22ch; text-align: right;
  font-family: var(--font-mono); font-size: 0.68rem; line-height: 1.45;
  letter-spacing: 0.03em; color: var(--text-muted);
  background: var(--surface-raised); border: 1px solid var(--border);
  border-radius: 10px; padding: 0.45rem 0.65rem;
}
.marvin-say:empty { display: none; }

/* --- moods --- */
.marvin-hud[data-mood="blank"] .mv-eye { fill: #7f979e; }
.marvin-hud[data-mood="blank"] .mv-eye-l { transform: scale(0.42); }
.marvin-hud[data-mood="blank"] .mv-eye-r { transform: scaleX(0.3); }
.marvin-hud[data-mood="blank"] .mv-emote::before { content: "..."; }

.marvin-hud[data-mood="confused"] .marvin-svg { transform: rotate(-9deg); }
.marvin-hud[data-mood="confused"] .mv-eye-l { transform: scale(0.78); }
.marvin-hud[data-mood="confused"] .mv-eye-r { transform: scaleX(0.42) scaleY(1.55); }
.marvin-hud[data-mood="confused"] .mv-emote::before { content: "?"; }

.marvin-hud[data-mood="panic"] .marvin-svg { animation: marvin-jitter 0.42s linear infinite; }
.marvin-hud[data-mood="panic"] .mv-eye-l { transform: scale(1.16); }
.marvin-hud[data-mood="panic"] .mv-eye-r { transform: scaleX(0.62) scaleY(1.7); }
.marvin-hud[data-mood="panic"] .mv-emote::before { content: "!!"; }

.marvin-hud[data-mood="smug"] .marvin-svg { transform: rotate(6deg); }
.marvin-hud[data-mood="smug"] .mv-eye-l { transform: scaleY(0.2); }
.marvin-hud[data-mood="smug"] .mv-eye-r { transform: scaleY(0.95) scaleX(0.78); }

.marvin-hud[data-mood="happy"] .mv-eye-l { transform: scaleY(0.5) translateY(-3px); }
.marvin-hud[data-mood="happy"] .mv-eye-r { transform: scaleY(0.72); }
.marvin-hud[data-mood="happy"] .mv-emote::before { content: "✓"; }

.marvin-hud[data-mood="shades"] .mv-shades { transform: scaleY(1); opacity: 1; }

@keyframes marvin-jitter {
  0%, 100% { transform: translateX(-1.5px) rotate(-2deg); }
  50%      { transform: translateX(1.5px) rotate(2deg); }
}

/* ============================================================
   Smaller screens
   ============================================================ */
@media (max-width: 1100px) {
  .slide { padding: 3rem 2.5rem 4rem; }
  .marvin-hud { display: none; }
  .title-layout { grid-template-columns: 1fr minmax(280px, 0.72fr); gap: 2.5rem; }
  .title-visual { width: min(360px, 34vw); }
  .cap-grid { grid-template-columns: repeat(2, 1fr); }
  .agent-row { grid-template-columns: repeat(3, 1fr); }
  .s-forgot .cols, .s-git .cols, .s-cta .cols, .s-network .cols { grid-template-columns: 1fr; gap: 2rem; }
  .prim-grid { grid-template-columns: 1fr; }
  .princ-list { columns: 1; }
  .runner-row { grid-template-columns: 1fr; gap: 0.3rem; }
  .verdict { justify-self: start; }
}

@media (max-width: 760px) {
  .title-layout { grid-template-columns: 1fr; text-align: center; }
  .s-title .logo { margin: 0 auto 2rem; }
  .title-location { justify-content: center; }
  .title-visual { display: none; }
  .close-trail { left: 0; right: 0; }
  .close-links { flex-wrap: wrap; }
  .close-links .close-logo { width: 94px; }
}

